/**
 * Generate src/game-server/handler/registry.modules.ts.
 *
 * Every file in src/game-server/handler/ that exports a `handlers` array is
 * discovered and concatenated. This keeps registry wiring out of the way while
 * modules are written in parallel — adding a handler file needs no shared-file
 * edit, and tsc still type-checks unregistered modules because the whole src
 * tree is in the program.
 *
 * Usage: node tools/gen-registry.js [--check]
 *        --check exits non-zero if the generated file is out of date.
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const dir = path.join(root, 'src', 'game-server', 'handler');
const outFile = path.join(dir, 'registry.modules.ts');

const SELF = path.basename(outFile);
const NON_MODULES = new Set([SELF, 'types.ts', 'registry.ts']);

function moduleFiles() {
    return fs
        .readdirSync(dir, { withFileTypes: true })
        .filter((e) => e.isFile() && e.name.endsWith('.ts') && !NON_MODULES.has(e.name))
        .map((e) => e.name)
        .sort();
}

function exportsHandlers(file) {
    const src = fs.readFileSync(path.join(dir, file), 'utf-8');
    return /export\s+const\s+handlers\s*:\s*HandlerEntry\[\]/.test(src);
}

function generate() {
    const modules = moduleFiles().filter(exportsHandlers);
    const names = modules.map((f) => f.replace(/\.ts$/, ''));

    const imports = names
        .map((n) => `import { handlers as ${ident(n)} } from './${n}';`)
        .join('\n');
    const spread = names.map((n) => `    ...${ident(n)},`).join('\n');

    return `// AUTO-GENERATED by tools/gen-registry.js - do not edit by hand.
// Concatenates the \`handlers\` table of every module in this directory.
import { HandlerEntry } from './types';
${imports}

export const moduleHandlers: HandlerEntry[] = [
${spread}
];
`;
}

function ident(moduleName) {
    const camel = moduleName.replace(/[^A-Za-z0-9]+(.)/g, (_, c) => c.toUpperCase());
    return `${camel}Handlers`;
}

const generated = generate();
const check = process.argv.includes('--check');
const existing = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf-8') : null;

if (check) {
    if (existing !== generated) {
        console.error('[gen-registry] registry.modules.ts is out of date; run node tools/gen-registry.js');
        process.exit(1);
    }
    console.log('[gen-registry] up to date');
    process.exit(0);
}

if (existing === generated) {
    console.log('[gen-registry] unchanged');
} else {
    fs.writeFileSync(outFile, generated, 'utf-8');
    console.log(`[gen-registry] wrote ${path.relative(root, outFile)}`);
}
